CAT = "frQuitter"; SEG = "QUI"
# Précautions nécessaires en quittant le véhicule : arrêt et stationnement, portières,
# immobilisation. Sources : Code de la route R110-2, R417-1 à R417-13, R416-12, R416-13.
Q = [
("Quelle est la différence entre l'arrêt et le stationnement ?",
 "Le conducteur reste à proximité", ["L'arrêt dure plus de dix minutes", "Le stationnement est payant", "Seul l'arrêt est sur la chaussée"],
 "Art. R110-2 : l'arrêt est l'immobilisation momentanée d'un véhicule, le conducteur restant aux commandes ou à proximité pour repartir ; le stationnement est toute autre immobilisation."),
("Vous voulez ouvrir votre portière côté rue alors qu'un cycliste arrive. Que dit le Code ?",
 "Ne pas ouvrir si c'est dangereux", ["Le cycliste doit vous éviter", "Ouvrir est permis à l'arrêt", "Ouvrir est permis au feu rouge"],
 "Art. R417-7 : il est interdit à tout occupant d'ouvrir une portière lorsque cela constitue un danger pour lui-même ou pour les autres usagers."),
("Avant de quitter votre véhicule, le Code vous impose :",
 "De prendre des précautions", ["De laisser le moteur tourner", "D'allumer les feux de route", "De laisser les clés au contact"],
 "Art. R417-8 : tout conducteur doit, avant de quitter son véhicule, prendre les précautions nécessaires pour éviter tout accident (frein serré, moteur coupé, rapport engagé si besoin)."),
("Garé en pente, quelle précaution prenez-vous en plus du frein de stationnement ?",
 "Engager une vitesse", ["Laisser le point mort", "Allumer les feux de détresse", "Laisser le moteur au ralenti"],
 "En pente, un rapport engagé (ou la position P d'une boîte automatique) et les roues braquées vers le trottoir complètent le frein de stationnement et évitent que la voiture ne parte."),
("En agglomération, sur une rue à double sens, de quel côté vous garez-vous ?",
 "Sur le côté droit", ["Sur le côté gauche", "Au milieu de la chaussée", "Du côté de votre choix"],
 "Art. R417-1 : en agglomération, sur une chaussée à double sens, le véhicule est arrêté ou stationné sur le côté droit, sauf dispositions différentes de l'autorité de police."),
("Dans une rue à sens unique en agglomération, où pouvez-vous vous garer ?",
 "À droite ou à gauche", ["Seulement à droite", "Seulement à gauche", "Nulle part"],
 "Art. R417-1 : sur une chaussée à sens unique en agglomération, l'arrêt et le stationnement sont possibles à droite ou à gauche, sauf disposition contraire."),
("Une rue est en stationnement unilatéral alterné semi-mensuel. Le 10 du mois, de quel côté vous garez-vous ?",
 "Côté impair", ["Côté pair", "Des deux côtés", "Nulle part"],
 "Art. R417-2 : du 1er au 15 du mois, le stationnement se fait du côté des numéros impairs ; du 16 à la fin du mois, du côté des numéros pairs."),
("En stationnement unilatéral alterné, à quel moment change-t-on de côté ?",
 "Le dernier jour, le soir", ["À minuit, le 1er du mois", "Le 15, à midi", "Le matin du 16"],
 "Art. R417-2 : le changement de côté s'opère le dernier jour de chaque période, entre 20 h 30 et 21 h, sauf autre horaire fixé."),
("Dans une zone de stationnement à durée limitée avec disque, où placez-vous le disque ?",
 "Derrière le pare-brise", ["Sur la plage arrière", "Dans la boîte à gants", "Sur le toit"],
 "Art. R417-3 : le dispositif de contrôle, conforme au modèle du ministère, est apposé à l'avant du véhicule, contre ou à proximité du pare-brise, et indique l'heure d'arrivée."),
("Vous laissez votre voiture au même endroit de la voie publique pendant plus de 7 jours. C'est :",
 "Un stationnement abusif", ["Toujours permis", "Permis dans votre rue", "Un stationnement gênant"],
 "Art. R417-12 : est abusif le stationnement ininterrompu d'un véhicule au même point de la voie publique pendant plus de sept jours, ou une durée plus courte fixée par arrêté."),
("Se garer près d'un virage sans visibilité est un stationnement :",
 "Dangereux", ["Gênant", "Abusif", "Autorisé la nuit"],
 "Art. R417-9 : est dangereux le stationnement à proximité des intersections, virages, sommets de côte et passages à niveau lorsque la visibilité est insuffisante."),
("Se garer en double file avec une voiture est un stationnement :",
 "Gênant", ["Dangereux", "Abusif", "Autorisé deux minutes"],
 "Art. R417-10 : le stationnement en double file est considéré comme gênant, sauf pour les deux-roues et les engins de déplacement personnel."),
("Se garer devant une borne de recharge sans recharger un véhicule électrique est :",
 "Un stationnement gênant", ["Toujours autorisé", "Un stationnement abusif", "Autorisé une heure"],
 "Art. R417-10 : est gênant le stationnement sur les emplacements réservés à la recharge des véhicules électriques."),
("Se garer sur une place réservée aux personnes handicapées sans la carte correspondante est :",
 "Très gênant", ["Gênant", "Abusif", "Toléré la nuit"],
 "Art. R417-11 : est très gênant le stationnement sur les emplacements réservés aux titulaires de la carte mobilité inclusion mention stationnement."),
("Votre voiture est garée juste avant un passage piéton, dans le sens de la circulation, hors emplacement. Jusqu'à quelle distance est-ce très gênant ?",
 "5 m", ["2 m", "10 m", "15 m"],
 "Art. R417-11 : est très gênant le stationnement d'un véhicule motorisé à moins de 5 mètres en amont d'un passage piéton, dans le sens de la circulation, hors emplacements aménagés."),
("Se garer devant une bouche d'incendie est un stationnement :",
 "Très gênant", ["Gênant", "Abusif", "Autorisé si on reste à côté"],
 "Art. R417-11 : le stationnement au droit des bouches d'incendie est très gênant ; il peut entraîner la mise en fourrière."),
("Garer une voiture sur le trottoir est :",
 "Très gênant", ["Gênant", "Autorisé deux roues dessus", "Autorisé la nuit"],
 "Art. R417-11 : est très gênant le stationnement des véhicules motorisés sur les trottoirs, à l'exception des motos, tricycles et cyclomoteurs (dont le stationnement y est gênant, art. R417-10)."),
("En agglomération, vous vous garez la nuit dans une rue bien éclairée. Devez-vous laisser des feux allumés ?",
 "Non, l'éclairage suffit", ["Oui, les feux de route", "Oui, les feux de détresse", "Oui, les feux de brouillard"],
 "Art. R416-16 : en agglomération, un véhicule à l'arrêt ou en stationnement n'a pas à être signalé lorsque l'éclairage public permet de le voir de loin."),
]
